const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial={name:'',career:'UI/UX Designer',academic:'University Student',discipline:'',skills:[],completed:[],quests:[],xp:0,onboarded:false,savedJobs:[],savedEvents:[],tracking:{},optin:false,cv:{name:'',email:'',summary:'',education:'',experience:'',projects:'',template:'Classic'},history:[],learningDays:[]};
let state;try{state={...initial,...JSON.parse(localStorage.getItem('gp-quest-v1')||'{}')};state.cv={...initial.cv,...state.cv}}catch{state=structuredClone(initial)}
const learningStreak=()=>{let days=new Set(state.learningDays||[]),d=new Date(),count=0,key=x=>x.toLocaleDateString('en-CA');if(!days.has(key(d)))d.setDate(d.getDate()-1);while(days.has(key(d))){count++;d.setDate(d.getDate()-1)}return count};
const save=()=>localStorage.setItem('gp-quest-v1',JSON.stringify(state));
const careers=['UI/UX Designer','Software Engineer','AI Engineer','Data Analyst','Digital Marketer','Product Manager','Business Analyst','Cybersecurity Specialist'];
const skillSets={'UI/UX Designer':['Design thinking','User research','Figma','Wireframing','Usability testing','Portfolio storytelling','Communication'],'Software Engineer':['Programming basics','JavaScript','Git','Web development','Testing','Project building','Communication'],'AI Engineer':['Python','Statistics','Machine learning','Data preparation','Model evaluation','Project building','Communication'],'Data Analyst':['Spreadsheets','Statistics','SQL','Python','Data visualization','Portfolio storytelling','Communication'],'Digital Marketer':['Marketing basics','Copywriting','SEO','Analytics','Campaign planning','Portfolio storytelling','Communication'],'Product Manager':['Product thinking','User research','Prioritization','Analytics','Roadmapping','Case studies','Communication'],'Business Analyst':['Business fundamentals','Spreadsheets','SQL','Requirements analysis','Process mapping','Case studies','Communication'],'Cybersecurity Specialist':['Networking basics','Linux','Security fundamentals','Risk assessment','Security testing','Lab projects','Communication']};
const required=()=>skillSets[state.career]||['Career research','Foundation knowledge','Core skills','Applied practice','Project building','Portfolio storytelling','Communication'];
const readiness=()=>Math.round(required().filter(s=>state.skills.includes(s)).length/required().length*100);
const nav=[['dashboard','◫','Dashboard'],['quest','⌘','My Career Quest'],['courses','▤','Explore Courses'],['mentor','✦','AI Mentor'],['skills','⬡','My Skills'],['cv','▧','CV Studio'],['jobs','▢','Job Match'],['events','▦','Events'],['leaderboard','♜','Leaderboard'],['profile','♙','My Profile']];
const levels=['Career Discovery','Foundation Skills','Core Skills','Real-World Practice','Portfolio Building','Career Preparation','Job Ready'];
const levelDesc=['Find your direction. Make it yours.','Build a foundation you can grow on.','Turn curiosity into capability.','Put your learning to work.','Show the world what you can do.','Tell your story with confidence.','Take your next step into work.'];
const courseData=[{title:'Career with AI',cat:'AI ESSENTIALS',duration:'3 hr 11 min',art:'Career<br>with AI',symbol:'✦',skill:'Career research',body:'Explore practical ways to use AI as a career companion.'},{title:'Design Thinking Essentials',cat:'DESIGN & CREATIVITY',duration:'2 hr 40 min',art:'Think it.<br>Design it.',symbol:'◈',skill:'Design thinking',body:'An illustrative course on defining problems and testing ideas.'},{title:'Programming Fundamentals',cat:'ADVANCED TECH SKILLS',duration:'3 hr 17 min',art:'Programming<br>Fundamentals',symbol:'⌘',skill:'Programming basics',body:'Build your understanding of programming concepts.'},{title:'Adobe Premiere Pro',cat:'DIGITAL SKILLS',duration:'9 hr 29 min',art:'Make your<br>next great edit.',symbol:'Pr',skill:'Video editing',body:'Discover the basics of a video editing workflow.'},{title:'Data Storytelling Lab',cat:'DATA & ANALYTICS',duration:'1 hr 50 min',art:'Let your<br>data speak.',symbol:'▥',skill:'Data visualization',body:'An illustrative practice course for communicating insights.'},{title:'Communication at Work',cat:'CAREER ESSENTIALS',duration:'1 hr 20 min',art:'Ideas worth<br>sharing.',symbol:'❞',skill:'Communication',body:'An illustrative course on explaining ideas clearly.'}];
function mascot(mood='happy'){return `<img class="mascot virus-character" src="assets/virus-transparent.png" alt="Virus, your career companion" width="1205" height="1306" decoding="async" data-mood="${esc(mood)}">`}

function person(i){let colors=['#f8c15c','#6255cb','#f58772','#079bc1','#eaa631','#54b59a','#e470aa','#5a729e'];let c=colors[i%8];return `<svg viewBox="0 0 150 170" role="img" aria-label="${['Dreamer','Coder','Designer','Explorer','Achiever','Thinker','Challenger','Career Guide'][i]}"><ellipse cx="75" cy="159" rx="38" ry="6" fill="#172a7810"/><path d="M59 125v29m30-29v29" stroke="#25384c" stroke-width="14" stroke-linecap="round"/><path d="M41 94q30-25 64 0l-7 43H49z" fill="${c}"/><path d="M45 98l-17 23m73-23 19-24" stroke="${c}" stroke-width="15" stroke-linecap="round"/><rect x="43" y="29" width="65" height="63" rx="25" fill="${i%2?'#bd805e':'#e8a684'}"/><path d="M41 51q-10-40 30-36q45-10 42 36l-17-4-3-17q-16 26-52 21" fill="#27384b"/><ellipse cx="63" cy="59" rx="8" ry="10" fill="white"/><ellipse cx="88" cy="59" rx="8" ry="10" fill="white"/><circle cx="65" cy="61" r="4" fill="#243b4b"/><circle cx="86" cy="61" r="4" fill="#243b4b"/><path d="M67 77q10 7 18-1" fill="none" stroke="#803f3f" stroke-width="3" stroke-linecap="round"/>${i===1?'<path d="M49 49h26v21H49zm29 0h26v21H78z" fill="none" stroke="#1b304a" stroke-width="3"/><rect x="48" y="110" width="53" height="29" rx="3" fill="#cbdaf0"/>':i===4?'<path d="M112 53h24v21q-12 15-24 0z" fill="#ffbf47"/><path d="M124 75v17m-9 0h18" stroke="#d99614" stroke-width="5"/>':i===2?'<path d="m120 86 9-33" stroke="#8057f5" stroke-width="6"/>':i===5?'<rect x="98" y="101" width="25" height="36" rx="3" fill="#ffdd84"/>':''}</svg>`}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function go(page){location.hash=page}
function heading(title,sub,eyebrow='YOUR NEXT CHAPTER'){return `<div class="page-title"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${sub}</p></div>`}
function courseCards(items=courseData.slice(0,3)){return `<div class="courses">${items.map(c=>{let i=courseData.indexOf(c);return `<article class="course"><div class="course-art"><b>${c.art}</b><span class="art-symbol">${c.symbol}</span></div><div class="course-body"><span class="eyebrow">${c.cat}</span><h3>${c.title}</h3><div class="course-meta"><span>◷ ${c.duration}</span><span>${[1,4,5].includes(i)?'Sample course':'GP Academy'}</span></div><div class="course-bottom"><span class="tag">${c.skill===required()[0]?'Recommended for you':'Build a new skill'}</span><button class="text-link" data-course="${i}">Explore →</button></div></div></article>`}).join('')}</div>`}
function compactJourney(){return `<div class="journey"><svg class="journey-line" viewBox="0 0 500 120" preserveAspectRatio="none"><path d="M40 15C110 15 90 95 190 95S240 15 320 15S400 95 470 95" stroke="#ddd8ed" fill="none" stroke-width="3" stroke-dasharray="5 5"/></svg><div class="journey-nodes">${levels.slice(0,4).map((n,i)=>`<div class="journey-node"><button class="node ${i>state.completed.length?'lock':i===state.completed.length?'current':''}" data-node="${i}">${i<state.completed.length?'✓':i===state.completed.length?'★':'♙'}</button><strong>${n}</strong><small>${i<state.completed.length?'Completed':i===state.completed.length?'You are here':'Up next'}</small></div>`).join('')}</div></div><div class="journey-footer"><span class="dot"></span> One small step today. A whole new future tomorrow.</div>`}
function dashboard(){let r=readiness();return `<div class="greeting"><div><h2>${state.name?`Welcome back, ${esc(state.name)}!`:'Your next chapter starts here.'} <span style="font-size:22px">☀</span></h2><p>Big dreams. Small steps. A little progress every day.</p></div><span class="pill">✧ &nbsp; ${state.onboarded?'Your personal career world':'Let’s find your direction'}</span></div><section class="hero"><div class="hero-copy"><span class="eyebrow">A BIG FUTURE STARTS WITH YOU</span><h1>Your dream career.<br><em>One quest closer.</em></h1><p>I’m Virus, your career buddy. Let’s turn your curiosity into skills, and your skills into possibilities.</p><div class="actions"><button class="btn" data-action="${state.onboarded?'continue':'onboard'}">${state.onboarded?'Continue my quest':'Start my career quest'} &nbsp; →</button><a class="text-link" href="#landing">Take a look around ↗</a></div></div><div class="hero-art"><div class="orb"></div><div class="bubble one">✦ &nbsp; Your potential? Unlimited.</div><div class="bubble two">Next stop:<br><b style="color:#8057f5">${esc(state.career)}</b></div>${mascot('welcoming')}<span class="spark">✧</span><div class="bubble three">★ &nbsp; A little better, every day</div></div></section><div class="stats"><div class="stat"><div class="stat-icon">✦</div><div><strong>${state.xp} <span style="font-size:11px;color:#99a4ad">XP</span></strong><small>Total experience</small></div></div><div class="stat"><div class="stat-icon" style="background:#fff4e4">♨</div><div><strong>${learningStreak()} <span style="font-size:11px;color:#99a4ad">day</span></strong><small>Learning streak</small></div></div><div class="stat"><div class="stat-icon" style="background:#f2edff">⬡</div><div><strong>${state.skills.length} <span style="font-size:11px;color:#99a4ad">skills</span></strong><small>In your toolkit · self-reported</small></div></div><div class="stat"><div class="stat-icon" style="background:#eaf8f0">⚑</div><div><strong>Level ${Math.floor(state.xp/200)+1}</strong><small>${levels[Math.min(state.completed.length,6)]}</small></div></div></div><div class="main-grid"><div><section class="card"><div class="section-head"><div><h2>My career journey</h2><p>Your destination: <b>${esc(state.career)}</b></p></div><a class="text-link" href="#quest">View full map →</a></div>${compactJourney()}</section><section class="course-section"><div class="section-head"><div><h2>Made for your next move</h2><p>Discover a skill. Open a new door.</p></div><a class="text-link" href="#courses">All courses →</a></div>${courseCards()}</section></div><aside><section class="card"><div class="section-head"><h2>Dream job readiness</h2><span style="color:#a9b4bc">ⓘ</span></div><div class="readiness"><div class="ring" style="--value:${r}%"><div class="ring-inner"><strong>${r}%</strong><small>SKILL ALIGNMENT</small></div></div><div><h3 style="font-size:13px">${esc(state.career)}</h3><p>Every skill brings you closer.<br>Let’s build your foundation.</p></div></div><div class="check-row"><span>Skills in your toolkit</span><b class="green">${required().filter(x=>state.skills.includes(x)).length} / ${required().length}</b></div><div class="progress"><span style="width:${r}%"></span></div><p style="font-size:9px;color:#9aa5b0">Preliminary, self-reported skill alignment. Not a hiring prediction.</p><a href="#skills" class="text-link">Explore my skill gaps →</a></section><section class="card daily"><div class="section-head"><h2>A little progress today</h2><span class="pill" style="font-size:9px;padding:4px 8px">${state.quests.length}/3</span></div>${[['lesson','Explore a learning lesson','5 minutes · build your foundation','+50 XP'],['practice','Take the skill challenge','Apply what you have learned','+30 XP'],['portfolio','Write a portfolio plan','Turn an idea into a project','+100 XP']].map(q=>`<div class="quest-row"><button aria-label="Open ${q[1]}" data-quest="${q[0]}">${state.quests.includes(q[0])?'✓':'→'}</button><div><strong>${q[1]}</strong><small>${q[2]}</small></div><span class="reward">${q[3]}</span></div>`).join('')}</section><section class="mentor-note">${mascot('encouraging')}<div><h3>A little nudge from Virus</h3><p>“You don’t need to know everything. You just need to take the next step.”</p><a class="text-link" href="#mentor" style="color:#8057f5">Let’s talk about it →</a></div></section></aside></div>`}
function landing(){return `<div class="landing"><section class="hero"><div class="hero-copy"><span class="eyebrow">GRAMEENPHONE ACADEMY · CAREER QUEST</span><h1>Your Dream Career<br><em>Starts Here.</em></h1><p>Meet your AI Career Mentor. Discover the skills you need, learn at your own pace, and turn your career goals into reality.</p><div class="actions"><button class="btn" data-action="onboard">Start My Career Quest →</button><a class="btn secondary" href="#courses">Explore Courses</a></div></div><div class="hero-art"><div class="orb"></div>${mascot('welcoming')}<div class="bubble one">Hello, future you! ✦</div><div class="bubble three">I’m Virus. We’ve got this.</div><span class="spark">✧</span></div></section><section class="landing-section"><div class="section-head"><h2>Trending at GP Academy</h2><a href="#courses" class="text-link">Explore all →</a></div>${courseCards()}</section><section class="landing-section"><span class="eyebrow">YOUR DREAM. YOUR PACE.</span><h2>Big possibilities. Three small steps.</h2><div class="grid3 steps">${[['Find your north star','Tell Virus where you are, and where you want to go.'],['Build your own path','Discover your skill gaps and a roadmap shaped around your goal.'],['Make your next move','Practice, create a portfolio, and prepare for opportunities.']].map(x=>`<div class="card"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></section><section class="landing-section"><h2>Where will your curiosity take you?</h2><div class="grid3">${careers.slice(0,6).map((c,i)=>`<button class="card" style="text-align:left" data-career="${c}"><span style="font-size:26px;color:#8057f5">${['◈','⌘','✦','▥','◎','◫'][i]}</span><h3 style="margin-top:16px">${c}</h3><small>Explore your path →</small></button>`).join('')}</div></section><section class="landing-section card"><div class="grid2"><div>${mascot('happy')}</div><div><span class="eyebrow">A BUDDY FOR EVERY BREAKTHROUGH</span><h2>Meet Virus.</h2><p>A little curious. A little playful. Always in your corner. Ask about your next skill, brainstorm a project, or make a plan for the week.</p><a class="btn" href="#mentor">Say hello to Virus →</a><p><small>Prototype mentor with simulated, career-aware responses.</small></p></div></div></section><section class="landing-section"><div class="section-head"><h2>A whole crew in your corner</h2><a class="text-link" href="#characters">Meet the characters →</a></div><div class="grid3">${[0,1,4].map(i=>`<div class="card" style="display:flex;align-items:center;gap:15px"><div style="width:95px">${person(i)}</div><div><h3>${['The Dreamer','The Coder','','','The Achiever'][i]}</h3><small>Every journey starts somewhere.</small></div></div>`).join('')}</div></section><section class="landing-section"><h2>Learn together. Go further.</h2><p>Discover sample workshops, career conversations, and community challenges.</p><div class="actions"><a class="btn secondary" href="#events">Explore events →</a><a class="btn secondary" href="#leaderboard">Meet the community →</a></div></section></div>`}
function quest(){return heading('Your dream has a roadmap.',`One milestone at a time. Your journey to ${esc(state.career)}.`,'MY CAREER QUEST')+`<div class="grid2"><div class="map">${levels.map((n,i)=>`<div class="map-step"><button class="node ${i>state.completed.length?'lock':i===state.completed.length?'current':''}" data-node="${i}" aria-label="Open ${n}">${state.completed.includes(i)?'✓':i===state.completed.length?'★':'♙'}</button><div><span class="eyebrow" style="font-size:8px">LEVEL ${i+1} · ${state.completed.includes(i)?'COMPLETE':i===state.completed.length?'YOUR NEXT STEP':'UPCOMING'}</span><h3>${n}</h3><p>${levelDesc[i]}</p><small>${i===0?'Discover your career':required()[Math.min(i-1,6)]} · +50 XP</small></div></div>`).join('')}</div><div><section class="card">${mascot('encouraging')}<h2>There’s no rush to the finish.</h2><p>Build a foundation, practice what you learn, then show your work. I’ll be here for every step.</p><button class="btn" data-node="${Math.min(state.completed.length,6)}">Take my next step →</button><p><small>These are simulated learning milestones, not certifications.</small></p></section><section class="card" style="margin-top:20px"><h3>Prefer to explore?</h3><p>You can browse every course without unlocking the map.</p><a class="text-link" href="#courses">Find something interesting →</a></section></div></div>`}
let courseFilter='All',courseSearch='';function courses(){let list=courseData.filter(c=>(courseFilter==='All'||c.cat.includes(courseFilter))&&c.title.toLowerCase().includes(courseSearch.toLowerCase()));return heading('Curiosity looks good on you.','Explore freely. Find a course that moves your story forward.','EXPLORE COURSES')+`<div class="filterrow"><input class="search" id="course-search" aria-label="Search courses" placeholder="Search your next skill…" value="${esc(courseSearch)}"><a class="text-link" href="https://grameenphone.academy/courses" target="_blank" rel="noopener">Visit GP Academy ↗</a></div><div class="chips">${['All','AI','DESIGN','TECH','DIGITAL','DATA','CAREER'].map(c=>`<button class="chip ${c===courseFilter?'active':''}" data-course-filter="${c}">${c==='All'?'All courses':c}</button>`).join('')}</div>${list.length?courseCards(list):'<div class="empty">No courses match. Try a different search.</div>'}<section class="card" style="margin-top:25px"><h3>Keep exploring, beyond the classroom</h3><p>Reference resources to support independent practice.</p><div class="actions"><a class="btn secondary" href="https://developer.mozilla.org/en-US/docs/Learn_web_development" target="_blank" rel="noopener">MDN Web Docs ↗</a><a class="btn secondary" href="https://www.figma.com/resource-library/" target="_blank" rel="noopener">Figma resource library ↗</a><a class="btn secondary" href="https://www.kaggle.com/learn" target="_blank" rel="noopener">Kaggle Learn ↗</a></div></section>`}
function skills(){return heading('Build a toolkit for your future.',`Your ${esc(state.career)} skill tree. Self-reported skills are not independently verified.`,'MY SKILLS')+`<div class="grid2">${required().map((s,i)=>`<details class="card"><summary style="cursor:pointer;font-weight:700">${state.skills.includes(s)?'✓':'○'} &nbsp; ${s} <span style="float:right;font-size:10px;color:#079bc1">${state.skills.includes(s)?'Self-reported':'To explore'}</span></summary><p>${s} helps you ${i===0?'understand the foundations of your chosen field':'turn ideas into practical, demonstrable work'} as a ${esc(state.career)}.</p><p><b>Practice:</b> ${i===0?'Explain the concept in your own words and identify one real-world example.':'Create a small project, document your choices, and ask someone for feedback.'}</p><small>Suggested prerequisite: ${i===0?'No prior knowledge':required()[i-1]}</small><div class="actions"><a class="btn secondary" href="#courses">Find learning resources</a><button class="text-link" data-skill="${esc(s)}">${state.skills.includes(s)?'Remove from my skills':'Add to my skills'}</button></div></details>`).join('')}</div>`}
let messages=[];function mentor(){return heading('A big dream. A friendly guide.','Ask, explore, or think out loud. Virus is in your corner.','MEET YOUR CAREER BUDDY')+`<div class="grid2" style="grid-template-columns:minmax(0,1.7fr) minmax(220px,1fr)"><section class="card" style="padding:0;overflow:hidden"><div class="section-head" style="padding:20px;margin:0;border-bottom:1px solid #eee"><div><h3 class="mentor-chat-title"><img src="assets/virus-transparent.png" alt="" class="mentor-avatar"> Virus</h3><small>Your career companion · Simulated demo</small></div><span class="tag">Here to help</span></div><div class="chat" id="chat">${[{role:'bot',text:`Hey ${state.name||'there'}! Your ${state.career} journey is yours to shape. What would you like to work on today?`},...messages].map(m=>`<div class="message ${m.role==='me'?'me':''}">${esc(m.text)}</div>`).join('')}</div><form class="chat-form" id="chat-form"><input aria-label="Message Virus" placeholder="Ask Virus anything about your next step…" required><button class="btn">Send ↗</button></form></section><aside><div class="card" style="text-align:center">${mascot('thinking')}<h3>Let’s figure it out together.</h3><p style="font-size:12px">Guidance uses your selected goal and self-reported skills. No live AI service is connected.</p></div><div class="chips">${['What should I learn next?','Make a 7-day learning plan','Suggest a portfolio project','Compare career paths','Practice an interview','Review my CV'].map(p=>`<button class="chip" data-prompt="${p}">${p} ↗</button>`).join('')}</div></aside></div>`}
function reply(q){let missing=required().filter(x=>!state.skills.includes(x)), next=missing[0]||required()[0],goal=state.career;if(/compar|different|switch/i.test(q)){let alt=careers.find(c=>q.toLowerCase().includes(c.toLowerCase())&&c!==goal)||'Data Analyst';let a=skillSets[alt]||required();return `Let’s compare ${goal} and ${alt}. Your choice stays yours.\n\nYour current path emphasizes ${required().slice(0,3).join(', ')}. ${alt} emphasizes ${a.slice(0,3).join(', ')}.\n\nTransferable skills: ${a.filter(x=>required().includes(x)).join(', ')||'communication and problem-solving'}. Try a small project in each field before deciding. You can change your goal in My Profile.`}if(/plan|week|7.day/i.test(q))return `Here’s a manageable week for your ${goal} goal:\nDay 1: Explore ${next} and write down what it means.\nDay 2: Study one beginner resource.\nDay 3: Recreate a small example.\nDay 4: Apply it to a problem you care about.\nDay 5: Ask a peer for feedback.\nDay 6: Improve and document your work.\nDay 7: Reflect and choose your next step.\n\nStart with 20 minutes a day. Adjust to your schedule.`;if(/project|portfolio/i.test(q))return `For ${goal}, try a small project around a Bangladeshi student’s everyday problem, such as finding campus events.\n\nDefine the problem, apply ${next}, make a simple solution, and ask two people for feedback. Document your process and what changed. A thoughtful small project is a great start.`;if(/interview/i.test(q))return `Let’s practice for ${goal}.\n\n“Tell me about a time you learned something unfamiliar to solve a problem.”\n\nUse a real example: the situation, your task, what you did, and the result. Send your answer or use it as a self-practice prompt. Never invent experience.`;if(/cv|resume/i.test(q))return state.cv.summary?`Your current summary says: “${state.cv.summary}”\n\nFor a ${goal} application, add a specific example from your real projects. Keep claims factual and use clear headings. ${state.cv.projects?'You have project content to develop.':'Add a genuine project before claiming practical experience.'} Open CV Studio to edit and export.`:`Start your CV with your actual education, a genuine project, and the skills you can discuss confidently. Your profile currently lists ${state.skills.join(', ')||'no skills yet'}. CV Studio has an editable template; fill in only information you can support.`;if(/job|apply/i.test(q))return `Explore ${goal} roles, then compare each job’s requirements against your own experience. Your next skill to investigate is ${next}. The Job Match page contains sample vacancies, not live opportunities. Follow a verified employer source before applying.`;return `For your ${goal} goal, a useful next step is ${next}. ${state.skills.length?`You’ve already reported ${state.skills.join(', ')}.`:'You haven’t added skills yet, so this is a preliminary suggestion.'}\n\nLearn the basics, try a small exercise, and reflect on what you can explain without help. The course library and quest map can help you get started. What would you like to explore next?`}
function sendChat(q){if(!q.trim())return;messages.push({role:'me',text:q},{role:'bot',text:reply(q)});render();$('#chat').scrollTop=$('#chat').scrollHeight}
function cv(){let c=state.cv;return heading('Let your story open doors.','Build an honest, clear CV. Every word stays yours to edit.','CV STUDIO')+`<div class="grid3" style="margin-bottom:24px">${['Classic','Modern','Minimal'].map(t=>`<button class="template ${c.template===t?'active':''}" data-template="${t}"><span style="color:#079bc1">▤</span> &nbsp; <b>${t}</b><p style="font-size:11px;margin-bottom:0">Clean, readable, single-column layout</p></button>`).join('')}</div><div class="grid2"><form class="card" id="cv-form"><div class="section-head"><h3>Your details</h3><button type="button" class="text-link" data-action="cv-draft">Use my profile ↗</button></div>${[['name','Full name'],['email','Email / contact'],['summary','Professional summary'],['education','Education'],['experience','Experience'],['projects','Projects & certifications']].map(([key,label])=>`<label class="field">${label}${['name','email'].includes(key)?`<input name="${key}" value="${esc(c[key])}" placeholder="${label}">`:`<textarea name="${key}" placeholder="Add your real ${label.toLowerCase()}">${esc(c[key])}</textarea>`}</label>`).join('')}<p><small>Tip: describe what you did, how you did it, and an honest result. No facts are generated for you.</small></p></form><div><div class="section-head"><h3>Live preview</h3><button class="btn" data-action="print">Export / Save PDF ↗</button></div><div class="cv-preview" id="cv-preview">${cvPreview()}</div><p><small><span id="cv-completeness">Completeness: ${Math.round(Object.keys(c).filter(k=>k!=='template'&&c[k].trim()).length/6*100)}%</span> · Use your browser’s “Save as PDF” in the print dialog. Simple headings support ATS readability; compatibility is not guaranteed.</small></p></div></div>`}
function cvPreview(){let c=state.cv;return `<div style="font-family:${c.template==='Classic'?'Georgia,serif':'inherit'};${c.template==='Minimal'?'color:#333':''}"><h2>${esc(c.name)||'Your name'}</h2><p>${esc(state.career)}</p><small>${esc(c.email)||'Your contact information'}</small>${[['summary','Profile'],['education','Education'],['experience','Experience'],['projects','Projects & certifications']].map(([k,t])=>`<h3>${t}</h3><p>${esc(c[k])||`Add your ${t.toLowerCase()} in the editor.`}</p>`).join('')}<h3>Skills</h3><p>${esc(state.skills.join(' · '))||'Add your skills in My Profile.'}</p></div>`}
const jobsData=[{company:'Studio North',title:'Junior UI/UX Designer',location:'Dhaka, Bangladesh',type:'Bangladesh',skills:['Figma','User research','Communication']},{company:'Orbit Labs',title:'Junior Software Engineer',location:'Remote · International',type:'Remote',skills:['JavaScript','Git','Testing']},{company:'Insight Collective',title:'Data Analyst Intern',location:'Dhaka, Bangladesh',type:'Internships',skills:['Spreadsheets','SQL','Data visualization']},{company:'Bright Ideas',title:'Digital Marketing Associate',location:'Singapore · International',type:'International',skills:['SEO','Copywriting','Analytics']}];let jobFilter='All';
function jobs(){let list=jobsData.filter((j,i)=>jobFilter==='All'||j.type===jobFilter||(jobFilter==='Saved'&&state.savedJobs.includes(i)));return heading('Your next opportunity is out there.','Explore possibilities and build the skills to meet them.','JOB MATCH')+`<div class="notice">Illustrative vacancies from fictional companies. No live applications or deadlines. Skill alignment is based on self-reported skills.</div><div class="chips">${['All','Bangladesh','International','Remote','Internships','Saved'].map(t=>`<button class="chip ${t===jobFilter?'active':''}" data-job-filter="${t}">${t}</button>`).join('')}</div><div class="grid2">${list.map(j=>{let i=jobsData.indexOf(j),n=Math.round(j.skills.filter(x=>state.skills.includes(x)).length/j.skills.length*100);return `<article class="card job"><div style="display:flex;align-items:center;gap:13px"><div class="job-logo">${j.company[0]}</div><div><h3>${j.title}</h3><small>${j.company} · Sample vacancy</small></div><button class="smallbtn save" data-save-job="${i}">${state.savedJobs.includes(i)?'♥ Saved':'♡ Save'}</button></div><p>${j.location} · ${j.type==='Internships'?'Internship':'Full-time'}<br>Application deadline: not applicable — demo listing</p><div class="chips" style="margin:0">${j.skills.map(s=>`<span class="tag" style="${state.skills.includes(s)?'':'background:#f2f3f8;color:#7c8499'}">${s}</span>`).join('')}</div><div><div class="check-row"><span>Skill alignment</span><b>${n}%</b></div><div class="progress"><span style="width:${n}%"></span></div></div><div class="actions"><button class="btn secondary" data-job="${i}">Explore role →</button><label style="font-size:11px">Track: <select aria-label="Application status for ${j.title}" data-track="${i}">${['Not started','Saved','Planning to Apply','Applied','Interview','Offer','Closed'].map(v=>`<option ${state.tracking[i]===v?'selected':''}>${v}</option>`).join('')}</select></label></div></article>`}).join('')||'<div class="empty">No saved roles yet. Save a role to find it here.</div>'}</div>`}
const eventData=[{title:'Design a better everyday',type:'Workshop',place:'Online',date:'24 OCT',time:'3:00 PM · Bangladesh time',desc:'A sample hands-on design thinking workshop.',icon:'◈'},{title:'Your first career conversation',type:'Career fair',place:'Dhaka',date:'30 OCT',time:'10:00 AM · Bangladesh time',desc:'A sample student networking and career event.',icon:'◎'},{title:'Build with AI weekend',type:'Hackathon',place:'Online',date:'07 NOV',time:'9:00 AM · Bangladesh time',desc:'A sample collaborative challenge for curious builders.',icon:'✦'}];let eventFilter='All',calendar=false;
function events(){let list=eventData.filter(x=>eventFilter==='All'||x.place===eventFilter);return heading('Good things happen together.','Make connections. Explore ideas. Find your people.','EVENTS & EXPERIENCES')+`<div class="notice">These are sample events for the prototype, not verified events or open registrations. Dates shown are illustrative, in 2026.</div><div class="section-head"><div class="chips">${['All','Online','Dhaka'].map(t=>`<button class="chip ${t===eventFilter?'active':''}" data-event-filter="${t}">${t}</button>`).join('')}</div><button class="smallbtn" data-action="calendar">${calendar?'Card view':'Calendar agenda'}</button></div><div class="${calendar?'':'grid3'}">${list.map(e=>{let i=eventData.indexOf(e);return `<article class="card job" style="margin-bottom:15px"><div style="padding:24px;border-radius:10px;background:${['#efe9ff','#e1f6f3','#fff2d9'][i]};display:flex;justify-content:space-between;align-items:center"><b>${e.date}</b><span style="font-size:35px">${e.icon}</span></div><span class="eyebrow">${e.type} · Free · Sample</span><h3>${e.title}</h3><small>${e.place} · ${e.time}</small><p>${e.desc} A chance to practice communication and discover different career perspectives.</p><button class="btn secondary" data-save-event="${i}">${state.savedEvents.includes(i)?'✓ Saved to my events':'Save event +'} </button></article>`}).join('')}</div>`}
function leaderboard(){return heading('Grow together. Cheer each other on.','A little friendly motivation. Your own progress comes first.','THE COMMUNITY')+`<div class="notice">Community names and XP are sample data. Participation is opt-in and your progress remains stored only in this browser.</div><div class="section-head"><div class="chips">${['Weekly XP','Friends','University','Career Track','Monthly Achievements'].map((t,i)=>`<button class="chip ${i===0?'active':''}" data-board="${t}">${t}</button>`).join('')}</div><button class="smallbtn" data-action="optin">${state.optin?'Opt out':'Join demo leaderboard'}</button></div><div id="board-context" class="eyebrow" style="margin-bottom:15px">WEEKLY XP · SAMPLE COMMUNITY</div><div class="grid3" style="margin-bottom:24px">${[['Nafisa','1,280',4],['Arafat','1,150',1],['Mehedi','980',0]].map(([n,x,i],rank)=>`<div class="card" style="text-align:center;background:${rank===0?'#fff9e9':'white'}"><div style="width:110px;margin:auto">${person(i)}</div><span class="eyebrow">#${rank+1} THIS WEEK</span><h3 style="margin-top:10px">${n}</h3><b style="color:#8057f5">${x} XP</b></div>`).join('')}</div><div class="card">${[['4','Sadia','850'],['5','Tanvir','720'],...(state.optin?[[String(6),state.name||'You',state.xp]]:[])].map(x=>`<div class="leader-row"><span>${x[0]}</span><span class="avatar">${esc(x[1][0])}</span><b>${esc(x[1])}</b><strong>${x[2]} XP</strong></div>`).join('')}<p style="font-size:12px;color:#86929c">${state.optin?'You’re part of this local demo. Keep going at your own pace.':'You’re focusing on personal progress. Join whenever it feels right.'}</p></div><div class="actions"><a href="#achievements" class="btn secondary">My achievements →</a></div>`}
function achievements(){return heading('Every little win counts.','Your achievements reflect actions completed in this prototype.','YOUR TROPHY SHELF')+`<div class="badge-grid">${[['✦','First step',state.onboarded],['★','Quest explorer',state.completed.length>0],['⬡','Skill collector',state.skills.length>=3],['⚑','Practice makes progress',state.quests.includes('practice')],['♜','Portfolio planner',state.quests.includes('portfolio')],['✧','Career adventurer',state.completed.length===7]].map(([i,t,on])=>`<div class="badge ${on?'':'locked'}"><span>${i}</span><b>${t}</b><p><small>${on?'Unlocked':'Keep exploring'}</small></p></div>`).join('')}</div>`}
function profile(){return heading('A future that feels like you.','Change direction, add a new skill, or celebrate how far you’ve come.','MY CAREER IDENTITY')+`<div class="grid2"><form class="card" id="profile-form"><label class="field">Your name<input name="name" value="${esc(state.name)}" placeholder="What should Virus call you?"></label><label class="field">Learning journey<select name="academic">${['School Student','HSC Student','University Student','Graduate','Working Professional'].map(x=>`<option ${state.academic===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Discipline<input name="discipline" value="${esc(state.discipline)}" placeholder="e.g. Computer Science"></label><label class="field">Dream career<input name="career" list="careers" value="${esc(state.career)}" required><datalist id="careers">${careers.map(x=>`<option>${x}</option>`).join('')}</datalist></label><p><small>Changing your career resets path milestones, so you can explore the new path. Your XP, CV and skills remain.</small></p><button class="btn">Save my profile →</button></form><div><div class="card">${mascot('proud')}<h3>There’s more than one way forward.</h3><p>Your goal is a direction, not a permanent decision. You can always change your mind.</p><div class="actions"><a class="btn secondary" href="#skills">Update my skills</a><a class="btn secondary" href="#achievements">My achievements</a></div></div><section class="card" style="margin-top:20px"><h3>Learning history</h3>${state.history.length?state.history.slice(-6).reverse().map(h=>`<p style="font-size:12px">✓ ${esc(h)}</p>`).join(''):'<p>Your story is just beginning. Complete a quest to add your first milestone.</p>'}</section></div></div>`}
function characters(){return heading('Meet your career crew.','Nine original characters. A world of possibilities.','THE GP ACADEMY FAMILY')+`<div class="grid3 characters">${['Virus','The Dreamer','The Coder','The Designer','The Explorer','The Achiever','The Thinker','The Challenger','The Career Guide'].map((n,i)=>`<div class="card" style="background:${['#e3f7fa','#fff4dc','#eee9ff','#ffe8e2','#e5f6ff','#fff4d4','#e2f5ec','#ffebf5','#e8edf9'][i]}">${i===0?mascot():person(i-1)}<h3>${n}</h3></div>`).join('')}</div><p style="margin-top:25px;color:#76838e">Meet Virus, your career companion — with the character artwork you chose.</p>`}
function render(){let page=location.hash.slice(1)||'dashboard';let title=nav.find(x=>x[0]===page)?.[2]||({landing:'Welcome',characters:'Meet the crew',achievements:'Achievements'}[page])||'Dashboard';const routes={dashboard,landing,quest,courses,skills,mentor,cv,jobs,events,leaderboard,profile,achievements,characters};$('#app').innerHTML=`<aside class="sidebar"><a href="#landing" class="brand" aria-label="GP Academy home"><span class="brandmark"></span><span class="brand-text">Grameenphone<br><strong>Academy</strong></span></a><div class="label">YOUR CAREER WORLD</div><nav class="nav">${nav.map(([id,icon,t])=>`<a href="#${id}" class="${page===id?'active':''}"><span class="icon">${icon}</span><span>${t}</span>${id==='mentor'?'<b class="new">NEW</b>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note"><strong style="font-size:12px">A little help. A big difference.</strong><p>Your next chapter starts with a conversation.</p><a href="#mentor" class="smallbtn" style="display:block;text-align:center;color:#8057f5">Ask Virus ✦</a></div><a class="user" href="#profile"><div class="avatar">${esc((state.name||'Y')[0])}</div><div><strong>${esc(state.name)||'Your career story'}</strong><br><small>${state.onboarded?'Career explorer':'Let’s get started'}</small></div><span style="margin-left:auto">⌄</span></a></div></aside><div class="shell"><header class="topbar"><a href="#landing" class="breadcrumb">Your career world <b>/ &nbsp; ${title}</b></a><div class="top-right"><span class="streak">♨ ${learningStreak()} day streak</span><span class="xp">✦ ${state.xp} XP</span><button data-action="notifications" aria-label="Notifications">♧</button><a class="avatar" href="#profile" aria-label="Profile">${esc((state.name||'Y')[0])}</a></div></header><main class="content">${(routes[page]||dashboard)()}<footer class="footer"><span>© 2026 GP Academy · Career Quest concept</span><span>Made for your next chapter. &nbsp; ✦</span></footer></main></div>`;if(page==='mentor'&&innerWidth<=560)$('.grid2').style.gridTemplateColumns='1fr';}
let onboarding={step:0,academic:state.academic,career:state.career,discipline:state.discipline,skills:[...state.skills],name:state.name};
function openModal(html){let d=$('#modal');d.innerHTML=`<div class="modal-top"><span class="eyebrow">GP ACADEMY · CAREER QUEST</span><button class="close" aria-label="Close dialog" data-action="close">×</button></div>${html}`;if(!d.open)d.showModal()}
function onboard(step=0){onboarding.step=step;let o=onboarding, titles=['Hey there! I’m Virus.','Where are you in your journey?','What does your dream look like?','What’s already in your toolkit?','Your Career Quest is ready!'];let body='';if(step===0)body=`<p>Big dreams start with a simple hello. Let’s find a path that feels like you.</p><label class="field">What should I call you? <small>(optional)</small><input id="on-name" value="${esc(o.name)}" placeholder="Your first name"></label>`;if(step===1)body=`<div class="options">${['School Student','HSC Student','University Student','Graduate','Working Professional'].map((s,i)=>`<button class="option ${o.academic===s?'selected':''}" data-academic="${s}">${['✏','▤','⌂','♧','▢'][i]} &nbsp; ${s}</button>`).join('')}</div><label class="field" style="margin-top:20px">What do you study or work in?<input id="on-discipline" list="disciplines" value="${esc(o.discipline)}" placeholder="Search or add a discipline"><datalist id="disciplines"><option>Computer Science</option><option>Business Administration</option><option>Engineering</option><option>Humanities</option><option>Design</option></datalist></label>`;if(step===2)body=`<div class="options">${careers.map((s,i)=>`<button class="option ${o.career===s?'selected':''}" data-oncareer="${s}">${['◈','⌘','✦','▥','◎','◫','▤','⬡'][i]} &nbsp; ${s}</button>`).join('')}</div><label class="field" style="margin-top:15px">Or choose your own direction<input id="on-career" placeholder="Your dream career" value="${careers.includes(o.career)?'':esc(o.career)}"></label>`;if(step===3)body=`<p>Select skills you feel familiar with. You can skip this and start fresh.</p><div class="chips">${(skillSets[o.career]||required()).map(s=>`<button class="chip ${o.skills.includes(s)?'active':''}" data-onskill="${s}">${o.skills.includes(s)?'✓ ': '+ '}${s}</button>`).join('')}</div><small>Self-reported, not assessed or verified. We’ll use these as a starting point.</small>`;if(step===4)body=`<div class="card" style="background:#eefafb"><span class="eyebrow">YOUR DESTINATION</span><h2 style="margin-top:10px">${esc(o.career)}</h2><p>Discover → Build foundations → Practice → Create → Prepare</p><p><b>First skill to explore:</b> ${(skillSets[o.career]||required()).find(s=>!o.skills.includes(s))||'Applied practice'}</p><p><b>First quest:</b> Discover what this career means to you.</p><a class="text-link" href="#courses" data-action="close">Suggested course: Career with AI →</a></div><p><small>Your roadmap is a sample based on your choices. Readiness is preliminary, and no prior achievements have been assumed.</small></p>`;openModal(`<div class="progress" style="margin-top:22px"><span style="width:${(step+1)*20}%"></span></div><div class="onboard-mentor">${mascot(step===4?'celebrating':step===2?'thinking':'welcoming')}<div><small>YOUR JOURNEY · ${step+1} OF 5</small><h2>${titles[step]}</h2></div></div>${body}<div class="modal-actions"><button class="smallbtn" data-action="${step===0?'close':'on-back'}">${step===0?'Explore first':'← Back'}</button><button class="btn" data-action="on-next">${['Let’s begin! →','That’s me →','Let’s explore →','Build my roadmap →','Enter my career world →'][step]}</button></div>`)}
function nextOnboard(){let o=onboarding;if(o.step===0)o.name=$('#on-name').value.trim();if(o.step===1)o.discipline=$('#on-discipline').value.trim();if(o.step===2&&$('#on-career').value.trim())o.career=$('#on-career').value.trim();if(o.step<4){onboard(o.step+1);return}if(state.career!==o.career)state.completed=[];Object.assign(state,{name:o.name,academic:o.academic,discipline:o.discipline,career:o.career,skills:o.skills,onboarded:true});save();$('#modal').close();go('dashboard');render();toast('Your story starts now. Welcome aboard! ✦')}
function courseModal(i){let c=courseData[i];openModal(`<h1 style="font-size:27px">${c.title}</h1><span class="tag">${c.cat} · ${c.duration}</span><p>${c.body}</p><p>This prototype previews a learning experience. Visit GP Academy for actual course content, availability, and enrollment.</p><div class="actions"><a class="btn" href="https://grameenphone.academy/courses" target="_blank" rel="noopener">Open GP Academy ↗</a><button class="btn secondary" data-quest="lesson">Try a sample lesson</button></div>`)}
function nodeModal(i){if(i>state.completed.length){openModal(`<h2 style="margin-top:25px">${levels[i]}</h2><p>${levelDesc[i]}</p><p>Complete ${levels[i-1]} to unlock this milestone. You can still explore all courses freely.</p><a class="btn" href="#courses" data-action="close">Explore courses →</a>`);return}if(state.completed.includes(i)){openModal(`<h2 style="margin-top:25px">✓ ${levels[i]} complete</h2><p>You’ve already earned the reward for this simulated milestone.</p><a href="#quest" data-action="close" class="btn">Back to my journey</a>`);return}let texts=[`A ${state.career} career grows through learning, practice, and evidence of your work. Start by exploring real role descriptions and noting recurring skills.`,`Your foundation begins with ${required()[0]}. Learn one concept, explain it in your own words, and look for an everyday example.`,`Core skills become stronger through deliberate practice. Choose ${required()[1]} and work through a small example before building independently.`,`Choose a real problem, make a small solution, and ask for feedback. Document what you changed and why.`,`A portfolio tells the story of a problem, your process, your contribution, and what you learned. Use real work and clearly label practice projects.`,`A strong CV is factual, readable, and specific. Prepare interview stories from your own education, projects, or experience.`,`Read job requirements carefully, identify gaps honestly, and apply when a role interests you. Learning progress is not a guarantee of employment.`];openModal(`<h2 style="margin-top:25px">${levels[i]}</h2><p>${texts[i]}</p><div class="notice">Simulated learning milestone · +50 XP once</div><h3>Quick reflection</h3><p>Which action best supports lasting career progress?</p><form id="node-form" data-index="${i}"><label style="display:block;padding:10px"><input type="radio" name="answer" value="wrong" required> Collect course titles without practicing</label><label style="display:block;padding:10px"><input type="radio" name="answer" value="right"> Practice a skill and document what you learn</label><label class="field">What is one concrete step you will take?<textarea name="reflection" minlength="20" required placeholder="Write at least 20 characters about your next action…"></textarea></label><button class="btn">Complete milestone →</button></form>`)}
function questModal(q){if(state.quests.includes(q)){toast('You’ve already completed this quest. Nice work!');return}let content=q==='portfolio'?`<p>Choose a problem you care about. What would you create, who would it help, and how would you test it?</p><label class="field">My project plan<textarea name="reflection" required minlength="60" placeholder="Write a specific plan (at least 60 characters)…"></textarea></label>`:`<p>${q==='lesson'?'A learning goal becomes useful when you practice it. Small projects help you turn information into understanding.':'Imagine you are learning a new skill. After finishing a tutorial, what is the most useful next step?'}</p><label style="display:block;padding:10px"><input type="radio" name="answer" value="wrong" required> Add it as an expert skill immediately</label><label style="display:block;padding:10px"><input type="radio" name="answer" value="right"> Apply it to a small example and reflect</label>`;openModal(`<h2 style="margin-top:25px">${q==='portfolio'?'Turn an idea into a plan':q==='lesson'?'Small steps, real learning':'Practice makes progress'}</h2><div class="notice">Sample exercise · Rewards are granted once.</div><form id="daily-form" data-quest-id="${q}">${content}<button class="btn" style="margin-top:20px">Complete challenge →</button></form>`)}
function award(xp,label){state.learningDays=[...new Set([...(state.learningDays||[]),new Date().toLocaleDateString('en-CA')])];state.xp+=xp;state.history.push(label);save();$('#modal').close();render();toast(`✦ ${xp} XP earned. ${label}!`)}
document.addEventListener('click',e=>{let el=e.target.closest('button,a');if(!el)return;let d=el.dataset;if(d.action){switch(d.action){case'onboard':onboarding={step:0,academic:state.academic,career:state.career,discipline:state.discipline,skills:[...state.skills],name:state.name};onboard();break;case'close':$('#modal').close();break;case'on-next':nextOnboard();break;case'on-back':onboard(Math.max(0,onboarding.step-1));break;case'continue':go('quest');break;case'notifications':toast('You’re all caught up. Your next quest is waiting!');break;case'cv-draft':state.cv.name=state.cv.name||state.name;state.cv.education=state.cv.education||[state.academic,state.discipline].filter(Boolean).join(' · ');save();render();toast('Your profile details are ready to edit. Add your real experience.');break;case'print':window.print();break;case'calendar':calendar=!calendar;render();break;case'optin':state.optin=!state.optin;save();render();break}}if(d.course!==undefined)courseModal(+d.course);if(d.node!==undefined)nodeModal(+d.node);if(d.quest)questModal(d.quest);if(d.academic){onboarding.academic=d.academic;onboard(1)}if(d.oncareer){onboarding.career=d.oncareer;onboard(2)}if(d.onskill){onboarding.skills=onboarding.skills.includes(d.onskill)?onboarding.skills.filter(x=>x!==d.onskill):[...onboarding.skills,d.onskill];onboard(3)}if(d.career){onboarding={...onboarding,career:d.career};onboard(0)}if(d.skill){state.skills=state.skills.includes(d.skill)?state.skills.filter(x=>x!==d.skill):[...state.skills,d.skill];save();render()}if(d.prompt)sendChat(d.prompt);if(d.template){state.cv.template=d.template;save();render()}if(d.courseFilter){courseFilter=d.courseFilter;render()}if(d.jobFilter){jobFilter=d.jobFilter;render()}if(d.eventFilter){eventFilter=d.eventFilter;render()}if(d.saveJob!==undefined){let i=+d.saveJob;state.savedJobs=state.savedJobs.includes(i)?state.savedJobs.filter(x=>x!==i):[...state.savedJobs,i];save();render()}if(d.saveEvent!==undefined){let i=+d.saveEvent;state.savedEvents=state.savedEvents.includes(i)?state.savedEvents.filter(x=>x!==i):[...state.savedEvents,i];save();render()}if(d.job!==undefined){let j=jobsData[+d.job];openModal(`<h2 style="margin-top:25px">${j.title}</h2><p>${j.company} · ${j.location}</p><div class="notice">Fictional sample vacancy. Applications are not accepted.</div><p><b>Required skills:</b> ${j.skills.join(', ')}</p><p><b>Skills to explore:</b> ${j.skills.filter(x=>!state.skills.includes(x)).join(', ')||'All listed skills are self-reported. Prepare evidence of your work.'}</p><p>Virus: ${j.title.includes(state.career)?'Build evidence of your skills with a clear project and portfolio.':'This may differ from your chosen path. Compare transferable skills and gaps before deciding. Your career choice is yours.'}</p><a class="btn" href="#mentor" data-action="close">Compare with Virus →</a>`)}if(d.board){document.querySelectorAll('[data-board]').forEach(b=>b.classList.toggle('active',b===el));$('#board-context').textContent=d.board==='Friends'?'FRIENDS · SAMPLE COMMUNITY — CONNECTED FRIENDS ARE NOT AVAILABLE':`${d.board.toUpperCase()} · SAMPLE COMMUNITY`;toast(`${d.board} selected. Rankings shown are illustrative.`)}});
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target,v=new FormData(f);if(f.id==='chat-form')sendChat(f.querySelector('input').value);if(f.id==='profile-form'){let newCareer=v.get('career').trim();if(newCareer!==state.career)state.completed=[];state.name=v.get('name').trim();state.academic=v.get('academic');state.discipline=v.get('discipline').trim();state.career=newCareer;save();render();toast('Your profile is updated. Your next chapter awaits.')}if(f.id==='node-form'){if(v.get('answer')!=='right'){toast('Try again: think about practicing what you learn.');return}let i=+f.dataset.index;if(state.completed.includes(i))return;state.completed.push(i);award(50,levels[i]+' completed')}if(f.id==='daily-form'){let q=f.dataset.questId;if(q!=='portfolio'&&v.get('answer')!=='right'){toast('Try again. A small project helps you apply your learning.');return}if(state.quests.includes(q))return;state.quests.push(q);if(q==='portfolio'){state.cv.projects=state.cv.projects||`Practice project plan: ${v.get('reflection')}`;}award(q==='portfolio'?100:q==='lesson'?50:30,q==='portfolio'?'Portfolio plan created':q==='lesson'?'Sample lesson completed':'Practice challenge completed')}});
document.addEventListener('input',e=>{if(e.target.closest('#cv-form')){state.cv[e.target.name]=e.target.value;save();$('#cv-preview').innerHTML=cvPreview();$('#cv-completeness').textContent='Completeness: '+Math.round(Object.keys(state.cv).filter(k=>k!=='template'&&state.cv[k].trim()).length/6*100)+'%'}if(e.target.id==='course-search'){let pos=e.target.selectionStart;courseSearch=e.target.value;render();$('#course-search').focus();$('#course-search').setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.dataset.track!==undefined){state.tracking[e.target.dataset.track]=e.target.value;save();toast('Application status saved in this browser.')}});
window.addEventListener('hashchange',()=>{render();scrollTo(0,0)});render();
